import { createClient, type SupabaseClient } from "@supabase/supabase-js"
import {
  buildAnswerRows,
  type AiReadinessAnswers,
} from "@/lib/ai-readiness"

export type AssessmentSubmissionPayload = {
  submissionId: string
  email: string
  answers: AiReadinessAnswers
  referralSource?: string
}

export type AssessmentSubmissionResult = {
  status: "sent"
  submissionId: string
}

let browserClient: SupabaseClient | null = null

function getSupabaseClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL
  const publishableKey =
    process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY ??
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

  if (!url || !publishableKey) {
    throw new Error(
      "Report email delivery is not configured. Please try again later.",
    )
  }

  if (!browserClient) {
    browserClient = createClient(url, publishableKey, {
      auth: {
        autoRefreshToken: false,
        detectSessionInUrl: false,
        persistSession: false,
      },
    })
  }

  return browserClient
}

export async function submitAiReadinessAssessment({
  submissionId,
  email,
  answers,
  referralSource,
}: AssessmentSubmissionPayload): Promise<AssessmentSubmissionResult> {
  const normalizedEmail = email.trim().toLowerCase()

  if (!normalizedEmail) {
    throw new Error("A work email is required to deliver the report.")
  }

  const { data, error } = await getSupabaseClient().functions.invoke(
    "submit-ai-readiness",
    {
      body: {
        submissionId,
        email: normalizedEmail,
        reportVersion: "1.0",
        referralSource: referralSource?.trim() || undefined,
        answers: buildAnswerRows(answers).map((answer) => ({
          questionId: answer.question_id,
          score: answer.score,
        })),
      },
    },
  )

  if (error) {
    throw new Error(
      "We could not email the report yet. Your answers are still available; please try again.",
    )
  }

  if (!data || data.status !== "sent") {
    throw new Error(
      typeof data?.message === "string"
        ? data.message
        : "We could not email the report yet. Please try again.",
    )
  }

  return {
    status: "sent",
    submissionId: data.submissionId,
  }
}
