"use client"

import {
  useEffect,
  useRef,
  useState,
  type FormEvent,
} from "react"
import Link from "next/link"
import { AnimatePresence, motion, useReducedMotion } from "framer-motion"
import {
  ArrowLeft,
  ArrowRight,
  ArrowUpRight,
  Check,
  CheckCircle2,
  Clock3,
  LockKeyhole,
  Mail,
  RotateCcw,
  ShieldCheck,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Container } from "@/components/ui/container"
import {
  AI_READINESS_PILLARS,
  AI_READINESS_QUESTIONS,
  calculateAiReadiness,
  type AiReadinessAnswers,
} from "@/lib/ai-readiness"
import { submitAiReadinessAssessment } from "@/lib/ai-readiness-submission"
import { useBookingUrl } from "@/lib/use-booking-url"
import { trackLeadEvent } from "@/hooks/use-cookie-consent"

type AssessmentScreen = "assessment" | "email" | "confirmation"

const OPTION_LABELS = ["A", "B", "C", "D"] as const

const REFERRAL_SOURCE_OPTIONS = [
  "Google search",
  "AI assistant (ChatGPT, Perplexity, etc.)",
  "LinkedIn",
  "YouTube",
  "Referral or word of mouth",
  "Other",
] as const

function countAnswered(answers: AiReadinessAnswers) {
  return AI_READINESS_QUESTIONS.filter((question) => answers[question.id]).length
}

function scrollToPageTop() {
  document.documentElement.scrollTop = 0
  document.body.scrollTop = 0
  window.scrollTo(0, 0)
}

function pushAssessmentEvent(event: string, payload?: Record<string, unknown>) {
  if (typeof window !== "undefined" && window.dataLayer) {
    window.dataLayer.push({ event, ...payload })
  }
}

export function AssessmentExperience() {
  const bookingUrl = useBookingUrl()
  const [screen, setScreen] = useState<AssessmentScreen>("assessment")
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0)
  const [answers, setAnswers] = useState<AiReadinessAnswers>({})
  const [email, setEmail] = useState("")
  const [referralSource, setReferralSource] = useState("")
  const [isAdvancing, setIsAdvancing] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [submissionError, setSubmissionError] = useState("")
  const [submissionId, setSubmissionId] = useState("")
  const headingRef = useRef<HTMLHeadingElement | null>(null)
  const advanceTimerRef = useRef<number | null>(null)
  const shouldReduceMotion = useReducedMotion()

  const currentQuestion = AI_READINESS_QUESTIONS[currentQuestionIndex]
  const answeredCount = countAnswered(answers)
  const progress = Math.round(
    ((currentQuestionIndex + 1) / AI_READINESS_QUESTIONS.length) * 100,
  )

  useEffect(() => {
    headingRef.current?.focus({ preventScroll: true })
  }, [currentQuestionIndex, screen])

  useEffect(() => {
    const frame = window.requestAnimationFrame(scrollToPageTop)
    return () => window.cancelAnimationFrame(frame)
  }, [screen])

  useEffect(() => {
    return () => {
      if (advanceTimerRef.current) {
        window.clearTimeout(advanceTimerRef.current)
      }
    }
  }, [])

  const selectAnswer = (score: number) => {
    if (isAdvancing) return

    if (Object.keys(answers).length === 0) {
      pushAssessmentEvent("assessment_start", {
        first_question_id: currentQuestion.id,
      })
    }

    pushAssessmentEvent("assessment_answer", {
      question_index: currentQuestionIndex + 1,
      question_id: currentQuestion.id,
      answer_score: score,
    })

    const nextAnswers = { ...answers, [currentQuestion.id]: score }
    setAnswers(nextAnswers)
    setIsAdvancing(true)

    advanceTimerRef.current = window.setTimeout(() => {
      if (currentQuestionIndex === AI_READINESS_QUESTIONS.length - 1) {
        const result = calculateAiReadiness(nextAnswers)
        pushAssessmentEvent("assessment_complete", {
          overall_score: result.score,
          maturity_stage: result.stage.name,
        })
        setSubmissionId((current) => current || crypto.randomUUID())
        setScreen("email")
      } else {
        setCurrentQuestionIndex((index) => index + 1)
      }
      setIsAdvancing(false)
    }, shouldReduceMotion ? 0 : 180)
  }

  const goBack = () => {
    if (advanceTimerRef.current) {
      window.clearTimeout(advanceTimerRef.current)
    }
    setIsAdvancing(false)

    if (screen === "email") {
      setScreen("assessment")
      setCurrentQuestionIndex(AI_READINESS_QUESTIONS.length - 1)
      return
    }

    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex((index) => index - 1)
    }
  }

  const submitEmail = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()

    if (
      answeredCount !== AI_READINESS_QUESTIONS.length ||
      !submissionId ||
      isSubmitting
    ) return

    setIsSubmitting(true)
    setSubmissionError("")

    try {
      const submission = await submitAiReadinessAssessment({
        submissionId,
        email,
        answers,
        referralSource: referralSource || undefined,
      })
      if (submission.status === "sent") {
        pushAssessmentEvent(
          "assessment_email_submit",
          referralSource ? { referral_source: referralSource } : undefined,
        )
        setScreen("confirmation")
      }
    } catch (error) {
      setSubmissionError(
        error instanceof Error
          ? error.message
          : "We could not prepare your report. Please try again.",
      )
    } finally {
      setIsSubmitting(false)
    }
  }

  const retakeAssessment = () => {
    setAnswers({})
    setCurrentQuestionIndex(0)
    setEmail("")
    setReferralSource("")
    setSubmissionError("")
    setSubmissionId("")
    setScreen("assessment")
  }

  if (screen === "confirmation") {
    return (
      <section className="relative min-h-[calc(100svh-4rem)] overflow-hidden bg-background">
        <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_50%_15%,color-mix(in_oklab,var(--primary)_16%,transparent),transparent_42%)]" />
        <Container className="relative grid min-h-[calc(100svh-4rem)] max-w-3xl place-items-center py-12">
          <motion.div
            animate={{ opacity: 1, y: 0 }}
            className="w-full rounded-2xl border border-border/80 bg-card p-7 text-center shadow-sm sm:p-10"
            initial={{ opacity: 0, y: shouldReduceMotion ? 0 : 16 }}
          >
            <div className="mx-auto grid size-20 place-items-center rounded-full border border-primary/25 bg-primary/15 text-primary">
              <Mail className="size-9" />
            </div>
            <p className="mt-6 text-xs font-semibold uppercase tracking-[0.14em] text-primary">
              Report sent
            </p>
            <h1
              className="mt-2 text-3xl font-bold tracking-tight text-foreground outline-none sm:text-4xl"
              ref={headingRef}
              tabIndex={-1}
            >
              Your report is on its way.
            </h1>
            <p className="mx-auto mt-4 max-w-lg text-base leading-7 text-muted-foreground">
              We emailed your three-page AI readiness PDF to{" "}
              <span className="font-semibold text-foreground">
                {email.trim().toLowerCase()}
              </span>
              . It may take a minute to arrive, so check your spam or promotions folder too.
            </p>
            <div className="mt-8 flex flex-col justify-center gap-3 sm:flex-row">
              <Button asChild className="h-11 px-5" id="btn-assessment-booking">
                <a
                  href={bookingUrl}
                  onClick={() => {
                    pushAssessmentEvent("assessment_booking_click", {
                      source: "report_confirmation",
                    })
                    trackLeadEvent({ source: "ai_readiness_confirmation" })
                  }}
                  rel="noopener noreferrer"
                  target="_blank"
                >
                  Book a Workflow Fit Call
                  <ArrowUpRight className="size-4" />
                </a>
              </Button>
              <Button
                className="h-11 px-5"
                id="btn-assessment-retake"
                onClick={retakeAssessment}
                type="button"
                variant="outline"
              >
                <RotateCcw className="size-4" />
                Retake assessment
              </Button>
            </div>
            <button
              suppressHydrationWarning
              className="mt-6 text-sm font-medium text-muted-foreground underline underline-offset-4 transition-colors hover:text-foreground"
              onClick={() => {
                setSubmissionId(crypto.randomUUID())
                setScreen("email")
              }}
              type="button"
            >
              Sent to the wrong email? Correct it
            </button>
          </motion.div>
        </Container>
      </section>
    )
  }

  return (
    <section className="relative min-h-[calc(100svh-4rem)] overflow-hidden bg-background">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_15%_12%,color-mix(in_oklab,var(--primary)_14%,transparent),transparent_30%),radial-gradient(circle_at_88%_70%,color-mix(in_oklab,var(--secondary)_12%,transparent),transparent_35%)]" />

      <Container className="relative max-w-6xl py-5 sm:py-7 md:py-8 lg:py-9">
        {screen === "assessment" ? (
          <>
            <div className="mb-5 flex flex-col gap-4 sm:mb-6">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <div>
                  <div className="inline-flex items-center text-xs font-semibold uppercase tracking-[0.14em] text-primary">
                    AI readiness assessment
                  </div>
                  <p className="mt-2 text-sm text-muted-foreground">
                    A practical baseline across five business capabilities
                  </p>
                </div>
                <div className="flex items-center gap-2 rounded-full border border-border/80 bg-card/80 px-3 py-1.5 text-xs font-medium text-muted-foreground shadow-sm backdrop-blur">
                  <Clock3 className="size-3.5 text-primary" />
                  About 3 minutes
                </div>
              </div>

              <div>
                <div className="mb-2 flex items-center justify-between gap-4 text-xs font-medium">
                  <span className="text-muted-foreground">
                    Question {currentQuestionIndex + 1} of {AI_READINESS_QUESTIONS.length}
                  </span>
                  <span className="font-semibold text-primary">{progress}%</span>
                </div>
                <div
                  aria-label="Assessment progress"
                  aria-valuemax={AI_READINESS_QUESTIONS.length}
                  aria-valuemin={1}
                  aria-valuenow={currentQuestionIndex + 1}
                  className="h-2 overflow-hidden rounded-full bg-muted shadow-inner"
                  role="progressbar"
                >
                  <motion.div
                    animate={{ width: `${progress}%` }}
                    className="h-full rounded-full bg-primary shadow-[0_0_12px_color-mix(in_oklab,var(--primary)_45%,transparent)]"
                    initial={false}
                    transition={{ duration: shouldReduceMotion ? 0 : 0.35, ease: "easeOut" }}
                  />
                </div>
              </div>
            </div>

            <div className="grid items-start gap-6 lg:grid-cols-[220px_minmax(0,1fr)] lg:gap-7">
              <aside className="hidden rounded-xl border border-border/80 bg-card/75 p-4 shadow-sm backdrop-blur lg:block">
                <p className="px-2 pb-3 text-xs font-semibold uppercase tracking-[0.14em] text-muted-foreground">
                  Capability pillars
                </p>
                <ol className="space-y-1">
                  {AI_READINESS_PILLARS.map((pillar) => {
                    const questions = AI_READINESS_QUESTIONS.filter(
                      (question) => question.pillar === pillar,
                    )
                    const complete = questions.every((question) => answers[question.id])
                    const active = currentQuestion.pillar === pillar

                    return (
                      <li
                        className={`flex items-center justify-between rounded-lg px-3 py-2.5 text-sm transition-colors ${
                          active
                            ? "bg-primary/10 font-semibold text-foreground"
                            : "text-muted-foreground"
                        }`}
                        key={pillar}
                      >
                        <span className="flex items-center gap-2.5">
                          <span
                            className={`size-2 rounded-full ${
                              active || complete ? "bg-primary" : "bg-border"
                            }`}
                          />
                          {pillar}
                        </span>
                        {complete && <Check className="size-4 text-primary" />}
                      </li>
                    )
                  })}
                </ol>
                <div className="mt-4 border-t border-border/70 px-2 pt-4">
                  <p className="text-xs leading-5 text-muted-foreground">
                    Choose the answer closest to today&apos;s reality, not the future target.
                  </p>
                </div>
              </aside>

              <div>
                <AnimatePresence initial={false} mode="wait">
                  <motion.div
                    animate={{ opacity: 1, y: 0 }}
                    className="rounded-2xl border border-border/80 bg-card/90 p-5 shadow-sm backdrop-blur sm:p-7 md:p-9"
                    exit={{ opacity: 0, y: shouldReduceMotion ? 0 : -10 }}
                    initial={{ opacity: 0, y: shouldReduceMotion ? 0 : 12 }}
                    key={currentQuestion.id}
                    transition={{ duration: shouldReduceMotion ? 0 : 0.22 }}
                  >
                    <div className="flex flex-wrap items-center justify-between gap-3">
                      <span className="inline-flex items-center rounded-full border border-primary/20 bg-primary/10 px-3 py-1 text-xs font-semibold text-primary">
                        {currentQuestion.pillar}
                      </span>
                      <span className="text-xs font-medium text-muted-foreground lg:hidden">
                        {answeredCount} of {AI_READINESS_QUESTIONS.length} answered
                      </span>
                    </div>

                    <h1
                      className="mt-5 max-w-3xl text-2xl font-bold leading-tight tracking-tight text-foreground outline-none sm:text-3xl md:text-4xl"
                      ref={headingRef}
                      tabIndex={-1}
                    >
                      {currentQuestion.text}
                    </h1>
                    <p className="mt-3 text-sm leading-6 text-muted-foreground sm:text-base">
                      Select the option that best describes your organization today.
                    </p>

                    <div className="mt-6 grid gap-3 sm:grid-cols-2" role="group" aria-label="Answer choices">
                      {currentQuestion.options.map((option, index) => {
                        const selected = answers[currentQuestion.id] === option.score

                        return (
                          <button
                            suppressHydrationWarning
                            aria-pressed={selected}
                            className={`group relative isolate flex min-h-20 w-full items-center gap-4 overflow-hidden rounded-xl border p-4 text-left transition-[border-color,background-color] duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/60 sm:min-h-24 sm:p-5 ${
                              selected
                                ? "border-primary/60 bg-primary/[0.07]"
                                : "border-border/80 bg-background/70 hover:border-primary/35 hover:bg-card/90"
                            }`}
                            disabled={isAdvancing}
                            key={option.label}
                            onClick={() => selectAnswer(option.score)}
                            type="button"
                          >
                            <span
                              aria-hidden="true"
                              className={`absolute inset-0 z-0 origin-left bg-gradient-to-r from-primary/[0.11] via-primary/[0.035] to-transparent transition-transform duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none ${
                                selected
                                  ? "scale-x-100"
                                  : "scale-x-0 group-hover:scale-x-100 group-focus-visible:scale-x-100"
                              }`}
                            />
                            <span
                              className={`relative z-10 grid size-9 shrink-0 place-items-center rounded-lg border text-sm font-bold transition-[background-color,border-color,color] duration-200 ${
                                selected
                                  ? "border-primary bg-primary text-primary-foreground"
                                  : "border-border bg-card text-muted-foreground group-hover:border-primary group-hover:bg-primary group-hover:text-primary-foreground group-focus-visible:border-primary group-focus-visible:bg-primary group-focus-visible:text-primary-foreground"
                              }`}
                            >
                              {selected ? <Check className="size-4" /> : OPTION_LABELS[index]}
                            </span>
                            <span className="relative z-10 font-medium leading-6 text-foreground">
                              {option.label}
                            </span>
                            <span
                              aria-hidden="true"
                              className={`relative z-10 ml-auto grid size-8 shrink-0 place-items-center rounded-full border text-primary transition-[background-color,border-color,transform,opacity] duration-200 motion-reduce:transition-none ${
                                selected
                                  ? "translate-x-0 border-primary/20 bg-primary/10 opacity-100"
                                  : "translate-x-1 border-transparent bg-transparent opacity-0 group-hover:translate-x-0 group-hover:border-primary/20 group-hover:bg-primary/10 group-hover:opacity-100 group-focus-visible:translate-x-0 group-focus-visible:border-primary/20 group-focus-visible:bg-primary/10 group-focus-visible:opacity-100"
                              }`}
                            >
                              <ArrowRight className="size-4" />
                            </span>
                          </button>
                        )
                      })}
                    </div>

                    <div className="mt-6 flex items-center justify-between border-t border-border/70 pt-5">
                      {currentQuestionIndex === 0 ? (
                        <Button asChild className="-ml-3 text-muted-foreground" variant="ghost">
                          <Link href="/">
                            <ArrowLeft className="size-4" />
                            Exit
                          </Link>
                        </Button>
                      ) : (
                        <Button
                          className="-ml-3 text-muted-foreground"
                          onClick={goBack}
                          type="button"
                          variant="ghost"
                        >
                          <ArrowLeft className="size-4" />
                          Previous
                        </Button>
                      )}
                      <p className="hidden text-xs text-muted-foreground sm:block">
                        Selecting an answer moves to the next question
                      </p>
                    </div>
                  </motion.div>
                </AnimatePresence>
              </div>
            </div>
          </>
        ) : (
          <div className="mx-auto max-w-lg py-5 sm:py-10">
            <button
              suppressHydrationWarning
              className="mb-8 inline-flex items-center gap-2 text-sm font-medium text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/50"
              onClick={goBack}
              type="button"
            >
              <ArrowLeft className="size-4" />
              Review last answer
            </button>

            <motion.div
              animate={{ opacity: 1, y: 0 }}
              className="overflow-hidden rounded-2xl border border-border/80 bg-card shadow-sm"
              initial={{ opacity: 0, y: shouldReduceMotion ? 0 : 16 }}
              transition={{ duration: shouldReduceMotion ? 0 : 0.3 }}
            >
              <div className="border-b border-border/70 bg-primary/[0.07] px-6 py-7 text-center sm:px-8 sm:py-8">
                <div className="mx-auto grid size-16 place-items-center rounded-full border border-primary/25 bg-primary/15 text-primary shadow-[0_0_24px_color-mix(in_oklab,var(--primary)_18%,transparent)]">
                  <CheckCircle2 className="size-8" />
                </div>
                <p className="mt-5 text-xs font-semibold uppercase tracking-[0.14em] text-primary">
                  All 15 questions complete
                </p>
                <h1
                  className="mt-2 text-3xl font-bold tracking-tight text-foreground outline-none sm:text-4xl"
                  ref={headingRef}
                  tabIndex={-1}
                >
                  Your report is ready.
                </h1>
                <p className="mx-auto mt-3 max-w-md text-sm leading-6 text-muted-foreground sm:text-base">
                  Enter your email and we&apos;ll send your readiness score, five-pillar analysis, recommendations, and 90-day roadmap as a PDF.
                </p>
              </div>

              <form className="space-y-5 p-6 sm:p-8" onSubmit={submitEmail}>
                <div>
                  <label className="text-sm font-semibold text-foreground" htmlFor="assessment-email">
                    Work email
                  </label>
                  <div className="relative mt-2">
                    <Mail className="pointer-events-none absolute left-4 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <input
                      autoComplete="email"
                      className="h-12 w-full rounded-lg border border-input bg-background pl-11 pr-4 text-base text-foreground shadow-xs transition-colors placeholder:text-muted-foreground/70 focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                      id="assessment-email"
                      inputMode="email"
                      maxLength={254}
                      onChange={(event) => setEmail(event.target.value)}
                      placeholder="you@company.com"
                      required
                      type="email"
                      value={email}
                    />
                  </div>
                </div>

                <div>
                  <label className="text-sm font-semibold text-foreground" htmlFor="assessment-referral-source">
                    How did you hear about us? <span className="font-normal text-muted-foreground">(optional)</span>
                  </label>
                  <select
                    className="mt-2 h-12 w-full appearance-none rounded-lg border border-input bg-background px-4 text-base text-foreground shadow-xs transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                    id="assessment-referral-source"
                    onChange={(event) => setReferralSource(event.target.value)}
                    value={referralSource}
                  >
                    <option value="">Select an option</option>
                    {REFERRAL_SOURCE_OPTIONS.map((option) => (
                      <option key={option} value={option}>
                        {option}
                      </option>
                    ))}
                  </select>
                </div>

                {submissionError && (
                  <p className="rounded-lg border border-destructive/30 bg-destructive/10 px-4 py-3 text-sm leading-6 text-destructive" role="alert">
                    {submissionError}
                  </p>
                )}

                <Button
                  className="h-12 w-full text-base"
                  disabled={isSubmitting}
                  id="btn-assessment-submit"
                  type="submit"
                >
                  {isSubmitting ? "Emailing your report…" : "Email my PDF report"}
                  {!isSubmitting && <ArrowRight className="size-4" />}
                </Button>

                <div className="flex items-start gap-3 rounded-lg bg-muted/60 p-4">
                  <LockKeyhole className="mt-0.5 size-4 shrink-0 text-primary" />
                  <p className="text-xs leading-5 text-muted-foreground">
                    Submitting allows Arbor AI Studio to store your email and assessment responses for report delivery. It does not subscribe you to marketing. See our{" "}
                    <Link className="font-medium text-foreground underline underline-offset-4" href="/privacy-policy">
                      Privacy Policy
                    </Link>
                    .
                  </p>
                </div>

                <div className="flex items-center justify-center gap-4 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                  <span className="inline-flex items-center gap-1.5">
                    <ShieldCheck className="size-3.5 text-primary" />
                    Private
                  </span>
                  <span aria-hidden="true">•</span>
                  <span>No marketing opt-in</span>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </Container>
    </section>
  )
}
